    static void validatePrepared(Element peer,String variant,String run,BiFunction<String,String,Optional<PlanCredentials>> keys)throws Exception {
        require(MetadataRoleKeyProbeTestCase.VARIANTS.contains(variant)&&MD.equals(peer.getNamespaceURI())&&"EntityDescriptor".equals(peer.getLocalName()));
        var sp=single(peer,MD,"SPSSODescriptor");var idp=single(peer,MD,"IDPSSODescriptor");boolean explicit=variant.contains("explicit"),flipped=variant.contains("idp-first");var operative=certificates(sp);var other=certificates(idp);validateKeyPurposes(operative,other,explicit);
        var first=keys.apply(run,"three-signing-keys-first").orElseThrow();var second=keys.apply(run,"three-signing-keys-second").orElseThrow();var third=keys.apply(run,"three-signing-keys").orElseThrow();
        require(new XmlSignatureVerifier().hasValidEnvelopedSignature(peer,first.certificate())&&operative.getFirst().fingerprint().equals(fingerprint(flipped?second.certificate():first.certificate()))&&other.getFirst().fingerprint().equals(fingerprint(flipped?first.certificate():second.certificate()))&&(explicit?operative.get(1).fingerprint().equals(fingerprint(third.certificate())):true));
    }
