    private static void validateKeyPurposes(List<RoleKey> sp,List<RoleKey> peer,boolean explicit){require(sp.size()==(explicit?2:1)&&peer.size()==(explicit?2:1));if(explicit){require("signing".equals(sp.get(0).use())&&"encryption".equals(sp.get(1).use())&&"signing".equals(peer.get(0).use())&&"encryption".equals(peer.get(1).use())&&peer.get(0).fingerprint().equals(peer.get(1).fingerprint())&&!sp.get(0).fingerprint().equals(sp.get(1).fingerprint())&&!peer.get(0).fingerprint().equals(sp.get(1).fingerprint()));}else require(sp.getFirst().use().isEmpty()&&peer.getFirst().use().isEmpty());require(!sp.getFirst().fingerprint().equals(peer.getFirst().fingerprint()));}
